mapper.select:
SELECT l.id, l.name, l.longitude, l.latitude, COALESCE(SUM(lps.heat_value), 0) AS heatValue, COALESCE(SUM(lps.poem_count), 0) AS poemCount, COALESCE(SUM(lps.poet_count), 0) AS poetCount FROM locations l LEFT JOIN location_poem_stats lps ON l.id = lps.location_id
lps.dynasty = #{dynasty}
AND lps.heat_value >= #{minHeat}
GROUP BY l.id, l.name, l.longitude, l.latitude ORDER BY heatValue DESC

SELECT DISTINCT p.name
FROM poets p
INNER JOIN poem_locations pl ON p.id IN (
    SELECT pm.poet_id FROM poems pm WHERE pm.id = pl.poem_id
)
WHERE pl.location_id = #{locationId}

    AND p.dynasty = #{dynasty}

LIMIT #{limit}

SELECT DISTINCT
    p.id,
    p.name,
    CASE WHEN p.id = #{poetId} THEN 1 ELSE 2 END AS `group`,
    p.dynasty,
    p.image_url AS imageUrl
FROM poets p
WHERE p.id = #{poetId}
   OR p.id IN (
       SELECT poet2_id FROM poet_relationships WHERE poet1_id = #{poetId}
       UNION
       SELECT poet1_id FROM poet_relationships WHERE poet2_id = #{poetId}
   )
